    var fehler = $('check-fehler'), weiter = $('check-weiter'), zurueck = $('check-zurueck');
    var L = $('m-laenge'), B = $('m-breite'), G = $('m-geschosse'), bild = $('m-bild');
    var NS = 'http://www.w3.org/2000/svg';
